package com.veyra.booking;import org.junit.jupiter.api.Test;import java.math.*;import static org.junit.jupiter.api.Assertions.*;class CommissionFormulaTest{@Test void tenPercent(){long p=10000;long c=BigDecimal.valueOf(p).multiply(BigDecimal.valueOf(1000)).divide(BigDecimal.valueOf(10000),0,RoundingMode.HALF_UP).longValue();assertEquals(1000,c);assertEquals(11000,p+c);}@Test void sixPercent(){long p=10000;long c=BigDecimal.valueOf(p).multiply(BigDecimal.valueOf(600)).divide(BigDecimal.valueOf(10000),0,RoundingMode.HALF_UP).longValue();assertEquals(600,c);}}